const owner = $env.GITHUB_REPO_OWNER || 'claude-builders-bounty';
const repo = $env.GITHUB_REPO_NAME || 'claude-builders-bounty';
const language = (($env.SUMMARY_LANGUAGE || 'EN').toUpperCase() === 'FR') ? 'FR' : 'EN';
const token = $env.GITHUB_TOKEN || '';
const now = new Date();
const until = now.toISOString();
const sinceDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = sinceDate.toISOString();

const headers = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-weekly-claude-summary'
};
if (token) headers.Authorization = `Bearer ${token}`;

async function getJson(url) {
  const response = await fetch(url, { headers });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`GitHub API failed ${response.status} for ${url}: ${text}`);
  }
  return response.json();
}

const base = `https://api.github.com/repos/${owner}/${repo}`;
const commitsUrl = `${base}/commits?since=${encodeURIComponent(since)}&until=${encodeURIComponent(until)}&per_page=100`;
const issuesUrl = `${base}/issues?state=closed&since=${encodeURIComponent(since)}&per_page=100`;
const pullsUrl = `${base}/pulls?state=closed&sort=updated&direction=desc&per_page=100`;

const [commits, closedIssues, closedPulls] = await Promise.all([
  getJson(commitsUrl),
  getJson(issuesUrl),
  getJson(pullsUrl)
]);

const mergedPulls = closedPulls.filter((pr) => pr.merged_at && new Date(pr.merged_at) >= sinceDate);
const plainIssues = closedIssues.filter((issue) => !issue.pull_request && issue.closed_at && new Date(issue.closed_at) >= sinceDate);

function compactCommit(commit) {
  return {
    sha: commit.sha.slice(0, 7),
    author: commit.commit.author?.name || commit.author?.login || 'unknown',
    date: commit.commit.author?.date,
    message: commit.commit.message.split('\n')[0],
    url: commit.html_url
  };
}

function compactIssue(issue) {
  return {
    number: issue.number,
    title: issue.title,
    author: issue.user?.login || 'unknown',
    closedAt: issue.closed_at,
    url: issue.html_url
  };
}

function compactPull(pr) {
  return {
    number: pr.number,
    title: pr.title,
    author: pr.user?.login || 'unknown',
    mergedAt: pr.merged_at,
    url: pr.html_url
  };
}

const activity = {
  repository: `${owner}/${repo}`,
  period: { since, until },
  language,
  commits: commits.map(compactCommit),
  closedIssues: plainIssues.map(compactIssue),
  mergedPulls: mergedPulls.map(compactPull)
};

const languageInstruction = language === 'FR'
  ? 'Write the summary in French.'
  : 'Write the summary in English.';

const prompt = `You are preparing a weekly engineering update for ${activity.repository}. ${languageInstruction}\n\nUse this JSON activity data to write a concise narrative summary with: 1) headline, 2) shipped highlights, 3) issue and PR outcomes, 4) notable contributors, 5) next-week watch items. Avoid inventing details.\n\n${JSON.stringify(activity, null, 2)}`;

return [{ json: { ...activity, prompt } }];

const content = $json.content || [];
const firstText = content.find((part) => part.type === 'text')?.text || 'No summary returned by Claude.';
const repository = $('Fetch GitHub Activity').first().json.repository;
const since = $('Fetch GitHub Activity').first().json.period.since.slice(0, 10);
const until = $('Fetch GitHub Activity').first().json.period.until.slice(0, 10);
const message = `**Weekly GitHub Summary: ${repository}**\n_${since} to ${until}_\n\n${firstText}`;
return [{ json: { repository, since, until, message } }];
